query GetAgentActionDetailsQuery($uuid: String!) {
  agentActionByUid(uid: $uuid) {
    contentId
    title
    name
    description
    purpose
    scriptInfo {
      runAs
      timeoutSeconds
      inputs {
        allowCustomValue
        description
        id
        name
        options
        type
        usedByMacOs
        usedByWindows
      }
      scriptWindows {
        name
      }
      scriptMacOs {
        name
      }
      impact {
        windows {
          behavior
          expectedImpact
        }
        macos: macOs {
          behavior
          expectedImpact
        }
      }
    }
  }
}
